1	// Regression coverage for subject-filtered audit pagination, with the
2	// emphasis on reads that race a growing chain. An auditor paging one
3	// subject's history sees that organization's chain interleaved with policy
4	// publishes, rollbacks and other subjects' decisions, so the subject's own
5	// records may sit far apart. These tests pin the contract of the existing
6	// AuditQuery/AuditPage entry points for that view:
7	//
8	//   - The subject filter selects exactly that subject's decision records
9	//     (allows and denials alike), preserving original sequence, request and
10	//     the complete decision explanation; policy changes and other subjects
11	//     never mix in, and an identical subject identifier in another
12	//     organization has no effect.
13	//   - A category filter combined with a subject filter is a conjunction,
14	//     never a fallback: a record must satisfy both.
15	//   - The page size bounds how many MATCHING records a page returns, not
16	//     how many chain positions were scanned; non-matching records between
17	//     matches never truncate a page early. Concatenating the pages along
18	//     the returned cursors yields the matching sequences in ascending
19	//     order with no duplicates or gaps, a legal start sequence excludes
20	//     earlier matches, and a page filled exactly while non-matching
21	//     records remain is followed by one empty page that terminates the
22	//     walk instead of repeating a cursor.
23	//   - The first page's end sequence and fingerprint constrain every later
24	//     page: records appended after the first query — even this subject's
25	//     own new allows and denials, or new policy publishes — never mix into
26	//     the pinned walk, every page carries the identical checkpoint, and
27	//     only a fresh query observes the new tail.
28	//   - A filter matching nothing returns an empty page that ends the walk,
29	//     never an error and never the unfiltered chain; a checkpoint whose
30	//     fingerprint was tampered with fails with ErrInvalidRange and
31	//     delivers no partial records.
32	//
33	// All of this is read-only: querying and paging never change the current
34	// policy version and never append audit records.
35	package darksafe
36	
37	import (
38		"errors"
39		"reflect"
40		"sync"
41		"testing"
42	)
43	
44	// subjectPageWalk pages a filtered query to exhaustion, returning the
45	// concatenated records and the checkpoint of every page seen. It fails the
46	// test if a cursor repeats (the walk would never terminate) or if any page
47	// carries a checkpoint different from the first page's.
48	func subjectPageWalk(t *testing.T, s *Store, org string, startSeq, pageSize int, kind, subject string) ([]AuditRecord, []Checkpoint) {
49		t.Helper()
50		page, err := s.AuditQuery(org, startSeq, pageSize, kind, subject)
51		if err != nil {
52			t.Fatalf("AuditQuery(%q, start %d): %v", org, startSeq, err)
53		}
54		var recs []AuditRecord
55		cps := []Checkpoint{page.Checkpoint}
56		seen := map[int]bool{}
57		for {
58			recs = append(recs, page.Records...)
59			if page.Next == 0 {
60				break
61			}
62			if seen[page.Next] {
63				t.Fatalf("cursor %d returned twice; paging never terminates", page.Next)
64			}
65			seen[page.Next] = true
66			page, err = s.AuditPage(page.Checkpoint, page.Next, pageSize, kind, subject)
67			if err != nil {
68				t.Fatalf("AuditPage(next %d): %v", page.Next, err)
69			}
70			if page.Checkpoint != cps[0] {
71				t.Fatalf("page checkpoint = %+v, want the first page's %+v", page.Checkpoint, cps[0])
72			}
73			cps = append(cps, page.Checkpoint)
74		}
75		return recs, cps
76	}
77	
78	// recordSeqs returns the sequences of the records in order.
79	func recordSeqs(recs []AuditRecord) []int {
80		seqs := make([]int, len(recs))
81		for i, r := range recs {
82			seqs[i] = r.Seq
83		}
84		return seqs
85	}
86	
87	// requireSubjectDecisions fails unless every record is a decision of the
88	// given subject in the given organization.
89	func requireSubjectDecisions(t *testing.T, org, subject string, recs []AuditRecord) {
90		t.Helper()
91		for _, r := range recs {
92			if r.Org != org || r.Kind != AuditDecision || r.Decision == nil {
93				t.Fatalf("subject filter leaked %+v", r)
94			}
95			if r.Decision.Request.Subject.ID != subject {
96				t.Fatalf("record seq %d belongs to subject %q, want %q",
97					r.Seq, r.Decision.Request.Subject.ID, subject)
98			}
99		}
100	}
101	
102	// subjectFilterFixture builds one organization whose chain interleaves the
103	// target subject's allows and denials with publishes, a rollback and other
104	// subjects' decisions:
105	//
106	//	seq 1  publish v1 (allow u1 read, deny u1 write)
107	//	seq 2  u1 read   -> allow (v1)
108	//	seq 3  u2 read   -> no-match denial
109	//	seq 4  u1 write  -> matched-deny (v1)
110	//	seq 5  publish v2 (empty set)
111	//	seq 6  u2 read   -> no-match denial
112	//	seq 7  rollback to v1 -> v3
113	//	seq 8  u1 read   -> allow (v3)
114	//
115	// It returns the submitted requests and returned decisions of the target
116	// subject so tests can verify the preserved content.
117	func subjectFilterFixture(t *testing.T, s *Store) (reqs map[int]OrgRequest, decisions map[int]Decision) {
118		t.Helper()
119		if _, err := s.Publish("acme", 0, []Policy{
120			allowPolicy("p-allow", "u1", "read", "org/a", false),
121			{ID: "p-deny", Subject: "u1", Action: "write", Scope: "org/a", Effect: EffectDeny},
122		}); err != nil {
123			t.Fatal(err)
124		}
125		reqs = map[int]OrgRequest{}
126		decisions = map[int]Decision{}
127		decide := func(seq int, subject, action string) {
128			t.Helper()
129			req := request("acme", subject, "r1", "org/a", action)
130			d := s.Decide("acme", req)
131			reqs[seq] = req
132			decisions[seq] = d
133		}
134		decide(2, "u1", "read")
135		decide(3, "u2", "read")
136		decide(4, "u1", "write")
137		if _, err := s.Publish("acme", 1, nil); err != nil {
138			t.Fatal(err)
139		}
140		decide(6, "u2", "read")
141		if _, err := s.Rollback("acme", 2, 1); err != nil {
142			t.Fatal(err)
143		}
144		decide(8, "u1", "read")
145		if !decisions[2].Allowed || decisions[4].Allowed || !decisions[8].Allowed {
146			t.Fatalf("fixture decisions broken: %+v", decisions)
147		}
148		return reqs, decisions
149	}
150	
151	// TestSubjectFilterSelectsOnlyThatSubjectsDecisions pins the filter rule:
152	// from a chain mixing policy changes, a rollback and other subjects, the
153	// subject view returns exactly the target subject's decisions — allows and
154	// denials — with their original sequences, full requests and complete
155	// decision explanations. The same subject identifier in another
156	// organization neither leaks in nor is affected.
157	func TestSubjectFilterSelectsOnlyThatSubjectsDecisions(t *testing.T) {
158		s := NewStore()
159		reqs, decisions := subjectFilterFixture(t, s)
160	
161		// The same subject identifier actively deciding in another organization.
162		if _, err := s.Publish("globex", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}); err != nil {
163			t.Fatal(err)
164		}
165		s.Decide("globex", request("globex", "u1", "r1", "org/a", "read"))
166		s.Decide("globex", request("globex", "u1", "r1", "org/a", "read"))
167	
168		recs, _ := subjectPageWalk(t, s, "acme", 1, 2, "", "u1")
169		if got := recordSeqs(recs); !reflect.DeepEqual(got, []int{2, 4, 8}) {
170			t.Fatalf("u1 seqs = %v, want [2 4 8]", got)
171		}
172		requireSubjectDecisions(t, "acme", "u1", recs)
173		// Original sequence, full request and complete decision explanation.
174		for _, r := range recs {
175			if !reflect.DeepEqual(r.Decision.Request, reqs[r.Seq]) {
176				t.Fatalf("seq %d request = %+v, want %+v", r.Seq, r.Decision.Request, reqs[r.Seq])
177			}
178			if !reflect.DeepEqual(r.Decision.Decision, decisions[r.Seq]) {
179				t.Fatalf("seq %d decision = %+v, want %+v", r.Seq, r.Decision.Decision, decisions[r.Seq])
180			}
181		}
182		// Both outcomes survive: the allow, the matched-deny and the later allow.
183		if !recs[0].Decision.Decision.Allowed || recs[1].Decision.Decision.Allowed ||
184			!recs[2].Decision.Decision.Allowed {
185			t.Fatalf("allow/deny outcomes not preserved: %+v", recs)
186		}
187		if recs[1].Decision.Decision.Reason != "matched deny policy" {
188			t.Fatalf("deny explanation = %+v", recs[1].Decision.Decision)
189		}
190	
191		// The other organization's identical subject identifier is invisible
192		// here, and its own view holds only its own records.
193		globex, _ := subjectPageWalk(t, s, "globex", 1, 1, "", "u1")
194		if got := recordSeqs(globex); !reflect.DeepEqual(got, []int{2, 3}) {
195			t.Fatalf("globex u1 seqs = %v, want [2 3]", got)
196		}
197		requireSubjectDecisions(t, "globex", "u1", globex)
198		if globex[0].Fingerprint == recs[0].Fingerprint {
199			t.Fatal("identical subject identifiers across organizations share a fingerprint")
200		}
201	
202		// Reads appended nothing and changed no version in either organization.
203		if got := len(drainAudit(t, s, "acme", "", "")); got != 8 {
204			t.Fatalf("acme records = %d, want 8; queries must not append", got)
205		}
206		if got := len(drainAudit(t, s, "globex", "", "")); got != 3 {
207			t.Fatalf("globex records = %d, want 3; queries must not append", got)
208		}
209		if v := s.CurrentVersion("acme"); v != 3 {
210			t.Fatalf("acme version = %d, want 3; queries must not republish", v)
211		}
212	}
213	
214	// TestSubjectAndCategoryFiltersAreConjunctive pins that specifying both a
215	// category and a subject requires both conditions: the category is not a
216	// fallback for the subject, nor the other way round.
217	func TestSubjectAndCategoryFiltersAreConjunctive(t *testing.T) {
218		s := NewStore()
219		subjectFilterFixture(t, s)
220	
221		// Decision category + subject: the subject's decisions only.
222		both, _ := subjectPageWalk(t, s, "acme", 1, 3, AuditDecision, "u1")
223		if got := recordSeqs(both); !reflect.DeepEqual(got, []int{2, 4, 8}) {
224			t.Fatalf("decision+u1 seqs = %v, want [2 4 8]", got)
225		}
226		// Policy-change category + subject: the subject made no policy change,
227		// so the result is empty — the subject's decisions must NOT be returned
228		// as a fallback, and the changes must NOT leak in either.
229		none, _ := subjectPageWalk(t, s, "acme", 1, 2, AuditPolicyChange, "u1")
230		if len(none) != 0 {
231			t.Fatalf("policy_change+u1 = %+v, want empty (filters are conjunctive)", none)
232		}
233		// A subject with no decisions at all under the decision category.
234		ghost, _ := subjectPageWalk(t, s, "acme", 1, 2, AuditDecision, "ghost")
235		if len(ghost) != 0 {
236			t.Fatalf("decision+ghost = %+v, want empty", ghost)
237		}
238	}
239	
240	// TestSubjectPagingCountsMatchesNotScannedRecords pins that the page size
241	// bounds returned matches, not scanned chain positions: non-matching
242	// records between matches never cut a page short, the concatenated walk is
243	// the ascending duplicate-free match list, and a page filled exactly while
244	// non-matching records remain is followed by one empty page that ends the
245	// walk.
246	func TestSubjectPagingCountsMatchesNotScannedRecords(t *testing.T) {
247		s := NewStore()
248		//	seq 1  publish v1 (allow u1)
249		//	seq 2  u1        seq 3-4  u2        seq 5  publish v2
250		//	seq 6  u3        seq 7-8  u1        seq 9  u2
251		//	seq 10 u1        seq 11   u2        seq 12 publish v3
252		if _, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}); err != nil {
253			t.Fatal(err)
254		}
255		decide := func(subject string) { s.Decide("acme", request("acme", subject, "r1", "org/a", "read")) }
256		decide("u1")              // 2
257		decide("u2")              // 3
258		decide("u2")              // 4
259		s.Publish("acme", 1, nil) // 5
260		decide("u3")              // 6
261		decide("u1")              // 7
262		decide("u1")              // 8
263		decide("u2")              // 9
264		decide("u1")              // 10
265		decide("u2")              // 11
266		s.Publish("acme", 2, nil) // 12
267		wantSeqs := []int{2, 7, 8, 10}
268	
269		// Page size 2: matches sit up to 5 chain positions apart, far beyond
270		// the page size; every page must still fill with matches.
271		page, err := s.AuditQuery("acme", 1, 2, "", "u1")
272		if err != nil {
273			t.Fatal(err)
274		}
275		if got := recordSeqs(page.Records); !reflect.DeepEqual(got, []int{2, 7}) {
276			t.Fatalf("page 1 seqs = %v, want [2 7]; non-matches truncated the page", got)
277		}
278		if page.Next != 8 {
279			t.Fatalf("page 1 next = %d, want 8 (first unscanned position)", page.Next)
280		}
281		page2, err := s.AuditPage(page.Checkpoint, page.Next, 2, "", "u1")
282		if err != nil {
283			t.Fatal(err)
284		}
285		if got := recordSeqs(page2.Records); !reflect.DeepEqual(got, []int{8, 10}) {
286			t.Fatalf("page 2 seqs = %v, want [8 10]", got)
287		}
288		// The page filled exactly while the non-matching seq 11-12 remain: the
289		// walk continues with one empty page...
290		if page2.Next != 11 {
291			t.Fatalf("page 2 next = %d, want 11", page2.Next)
292		}
293		page3, err := s.AuditPage(page2.Checkpoint, page2.Next, 2, "", "u1")
294		if err != nil {
295			t.Fatal(err)
296		}
297		// ...which terminates the walk instead of repeating the position.
298		if len(page3.Records) != 0 || page3.Next != 0 {
299			t.Fatalf("trailing page = %+v, want empty with next 0", page3)
300		}
301	
302		// Other page sizes agree: the concatenation is always the ascending
303		// match list with no duplicates or gaps.
304		for _, size := range []int{1, 3, 4, 100} {
305			recs, _ := subjectPageWalk(t, s, "acme", 1, size, "", "u1")
306			if got := recordSeqs(recs); !reflect.DeepEqual(got, wantSeqs) {
307				t.Fatalf("page size %d seqs = %v, want %v", size, got, wantSeqs)
308			}
309			requireSubjectDecisions(t, "acme", "u1", recs)
310		}
311	
312		// A legal start sequence excludes earlier matches instead of
313		// backfilling them, wherever the start lands.
314		fromEight, _ := subjectPageWalk(t, s, "acme", 8, 2, "", "u1")
315		if got := recordSeqs(fromEight); !reflect.DeepEqual(got, []int{8, 10}) {
316			t.Fatalf("from seq 8 = %v, want [8 10]", got)
317		}
318		fromNine, _ := subjectPageWalk(t, s, "acme", 9, 2, "", "u1")
319		if got := recordSeqs(fromNine); !reflect.DeepEqual(got, []int{10}) {
320			t.Fatalf("from seq 9 = %v, want [10]", got)
321		}
322		// A start beyond the last match scans the tail and ends empty.
323		fromEleven, _ := subjectPageWalk(t, s, "acme", 11, 2, "", "u1")
324		if len(fromEleven) != 0 {
325			t.Fatalf("from seq 11 = %+v, want empty", fromEleven)
326		}
327	}
328	
329	// TestSubjectQueryCheckpointPinsAgainstLaterAppends is the core
330	// read-while-appending guarantee: once the first page pinned an end
331	// sequence and fingerprint, later appends — the same subject's new allows
332	// AND denials, other subjects' decisions, new publishes — never mix into
333	// the pinned walk, every page carries the identical checkpoint, and only a
334	// freshly started query observes the appended tail.
335	func TestSubjectQueryCheckpointPinsAgainstLaterAppends(t *testing.T) {
336		s := NewStore()
337		if _, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}); err != nil {
338			t.Fatal(err)
339		}
340		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))  // seq 2, u1 allow
341		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))  // seq 3
342		s.Decide("acme", request("acme", "u1", "r1", "org/a", "write")) // seq 4, u1 deny
343		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))  // seq 5
344	
345		first, err := s.AuditQuery("acme", 1, 1, "", "u1")
346		if err != nil {
347			t.Fatal(err)
348		}
349		if got := recordSeqs(first.Records); !reflect.DeepEqual(got, []int{2}) {
350			t.Fatalf("first page seqs = %v, want [2]", got)
351		}
352		cp := first.Checkpoint
353		if cp.EndSeq != 5 {
354			t.Fatalf("pinned end = %d, want 5", cp.EndSeq)
355		}
356	
357		// The chain grows after the pin: the same subject produces a new allow
358		// and a new denial, another subject decides, and a new policy version
359		// is published.
360		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 6, u1 allow
361		if _, err := s.Publish("acme", 1, nil); err != nil {           // seq 7
362			t.Fatal(err)
363		}
364		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 8, u1 deny (v2 empty)
365		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read")) // seq 9
366	
367		// Paging along the original checkpoint still sees only the pinned
368		// range's matches, and every page repeats the first checkpoint exactly.
369		second, err := s.AuditPage(cp, first.Next, 1, "", "u1")
370		if err != nil {
371			t.Fatal(err)
372		}
373		if got := recordSeqs(second.Records); !reflect.DeepEqual(got, []int{4}) {
374			t.Fatalf("second page seqs = %v, want [4]; appended u1 records leaked", got)
375		}
376		if second.Checkpoint != cp {
377			t.Fatalf("second page checkpoint = %+v, want pinned %+v", second.Checkpoint, cp)
378		}
379		if second.EndSeq != 5 {
380			t.Fatalf("second page end = %d, want pinned 5", second.EndSeq)
381		}
382		third, err := s.AuditPage(cp, second.Next, 1, "", "u1")
383		if err != nil {
384			t.Fatal(err)
385		}
386		if len(third.Records) != 0 || third.Next != 0 || third.Checkpoint != cp {
387			t.Fatalf("final pinned page = %+v, want empty, next 0, pinned checkpoint", third)
388		}
389	
390		// A fresh query pins the new head and sees the appended u1 records —
391		// both the allow and the denials.
392		fresh, _ := subjectPageWalk(t, s, "acme", 1, 2, "", "u1")
393		if got := recordSeqs(fresh); !reflect.DeepEqual(got, []int{2, 4, 6, 8}) {
394			t.Fatalf("fresh query seqs = %v, want [2 4 6 8]", got)
395		}
396		if !fresh[2].Decision.Decision.Allowed || fresh[3].Decision.Decision.Allowed {
397			t.Fatalf("appended allow/deny outcomes wrong: %+v", fresh[2:])
398		}
399	
400		// All the reading was read-only.
401		if got := len(drainAudit(t, s, "acme", "", "")); got != 9 {
402			t.Fatalf("records = %d, want 9; queries must not append", got)
403		}
404		if v := s.CurrentVersion("acme"); v != 2 {
405			t.Fatalf("version = %d, want 2; queries must not republish", v)
406		}
407	}
408	
409	// TestSubjectPagingWhileAppendsRunConcurrently races a subject-filtered
410	// walk against concurrent appends of the same subject's decisions, other
411	// subjects' decisions and publishes. The walk must return exactly the
412	// matches inside the range pinned by its first page — no appended record
413	// mixes in, no match is dropped, no cursor repeats.
414	func TestSubjectPagingWhileAppendsRunConcurrently(t *testing.T) {
415		s := NewStore()
416		policies := []Policy{
417			allowPolicy("p-u1", "u1", "read", "org/a", false),
418			allowPolicy("p-u2", "u2", "read", "org/a", false),
419		}
420		if _, err := s.Publish("acme", 0, policies); err != nil {
421			t.Fatal(err)
422		}
423		//	seq 1 publish, then u1 at every even and u2 at every odd sequence.
424		const pinnedPairs = 20
425		for i := 0; i < pinnedPairs; i++ {
426			s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
427			s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
428		}
429		wantSeqs := make([]int, 0, pinnedPairs)
430		for i := 0; i < pinnedPairs; i++ {
431			wantSeqs = append(wantSeqs, 2*i+2)
432		}
433	
434		first, err := s.AuditQuery("acme", 1, 2, "", "u1")
435		if err != nil {
436			t.Fatal(err)
437		}
438		cp := first.Checkpoint
439		pinnedEnd := cp.EndSeq
440	
441		// Writers append a fixed burst of the same subject's decisions, other
442		// subjects' decisions and publishes while the walk runs.
443		var wg sync.WaitGroup
444		for _, subject := range []string{"u1", "u2"} {
445			wg.Add(1)
446			go func(subject string) {
447				defer wg.Done()
448				for i := 0; i < 50; i++ {
449					s.Decide("acme", request("acme", subject, "r1", "org/a", "read"))
450				}
451			}(subject)
452		}
453		wg.Add(1)
454		go func() {
455			defer wg.Done()
456			for i := 0; i < 20; i++ {
457				// Conflicts are expected and irrelevant; successful publishes
458				// append policy-change records to the racing chain.
459				s.Publish("acme", s.CurrentVersion("acme"), policies)
460			}
461		}()
462	
463		// Page the pinned query to exhaustion while the writers run.
464		recs := append([]AuditRecord(nil), first.Records...)
465		seen := map[int]bool{}
466		page := first
467		for page.Next != 0 {
468			if seen[page.Next] {
469				t.Fatalf("cursor %d repeated under concurrency", page.Next)
470			}
471			seen[page.Next] = true
472			page, err = s.AuditPage(cp, page.Next, 2, "", "u1")
473			if err != nil {
474				t.Fatalf("AuditPage under concurrency: %v", err)
475			}
476			if page.Checkpoint != cp {
477				t.Fatalf("checkpoint drifted under concurrency: %+v vs %+v", page.Checkpoint, cp)
478			}
479			recs = append(recs, page.Records...)
480		}
481		wg.Wait()
482	
483		// Exactly the pinned range's u1 decisions, ascending, nothing appended
484		// after the pin.
485		if got := recordSeqs(recs); !reflect.DeepEqual(got, wantSeqs) {
486			t.Fatalf("concurrent walk seqs = %v, want %v", got, wantSeqs)
487		}
488		requireSubjectDecisions(t, "acme", "u1", recs)
489		for _, r := range recs {
490			if r.Seq > pinnedEnd {
491				t.Fatalf("record seq %d leaked past the pinned end %d", r.Seq, pinnedEnd)
492			}
493		}
494	
495		// The appended records are real and visible to a fresh query.
496		fresh := drainAudit(t, s, "acme", "", "u1")
497		if len(fresh) != len(recs)+50 {
498			t.Fatalf("fresh query sees %d u1 records, want %d pinned + 50 appended", len(fresh), len(recs))
499		}
500		if got := recordSeqs(fresh[:len(recs)]); !reflect.DeepEqual(got, wantSeqs) {
501			t.Fatalf("fresh query prefix = %v, want the pinned %v", got, wantSeqs)
502		}
503	}
504	
505	// TestSubjectQueryWithoutMatchesReturnsEmpty pins the no-match behaviour:
506	// an unknown subject — in a chain full of other records, or in an
507	// organization with no records at all — yields an empty page that ends the
508	// walk immediately. It is not an error and never falls back to returning
509	// the unfiltered chain.
510	func TestSubjectQueryWithoutMatchesReturnsEmpty(t *testing.T) {
511		s := NewStore()
512		subjectFilterFixture(t, s) // 8 records, none of them subject "ghost"
513	
514		page, err := s.AuditQuery("acme", 1, 4, "", "ghost")
515		if err != nil {
516			t.Fatalf("no-match query err = %v, want nil", err)
517		}
518		if len(page.Records) != 0 || page.Next != 0 {
519			t.Fatalf("no-match page = %+v, want empty with next 0", page)
520		}
521		if page.Checkpoint.EndSeq != 8 {
522			t.Fatalf("no-match checkpoint end = %d, want the pinned head 8", page.Checkpoint.EndSeq)
523		}
524		// Same under the explicit decision category, and from a later start.
525		if recs, _ := subjectPageWalk(t, s, "acme", 1, 2, AuditDecision, "ghost"); len(recs) != 0 {
526			t.Fatalf("no-match walk = %+v, want empty (not the unfiltered chain)", recs)
527		}
528		if recs, _ := subjectPageWalk(t, s, "acme", 6, 2, "", "ghost"); len(recs) != 0 {
529			t.Fatalf("no-match walk from seq 6 = %+v, want empty", recs)
530		}
531	
532		// An organization with no records at all answers the same way.
533		empty, err := s.AuditQuery("blank", 1, 4, "", "ghost")
534		if err != nil {
535			t.Fatalf("empty-org query err = %v, want nil", err)
536		}
537		if len(empty.Records) != 0 || empty.Next != 0 || empty.Checkpoint.EndSeq != 0 {
538			t.Fatalf("empty-org page = %+v, want the empty genesis page", empty)
539		}
540	}
541	
542	// TestSubjectPagingRejectsTamperedCheckpointFingerprint pins that a
543	// checkpoint whose fingerprint was altered fails with the existing
544	// ErrInvalidRange and delivers no partial records — the walk must not
545	// continue over a checkpoint that no longer proves the pinned range.
546	func TestSubjectPagingRejectsTamperedCheckpointFingerprint(t *testing.T) {
547		s := NewStore()
548		subjectFilterFixture(t, s)
549	
550		first, err := s.AuditQuery("acme", 1, 1, "", "u1")
551		if err != nil {
552			t.Fatal(err)
553		}
554		if len(first.Records) != 1 || first.Next == 0 {
555			t.Fatalf("first page = %+v, want one record and a live cursor", first)
556		}
557	
558		// An altered fingerprint: the error, never partial records.
559		forged := first.Checkpoint
560		forged.Fingerprint = "00"
561		page, err := s.AuditPage(forged, first.Next, 1, "", "u1")
562		if !errors.Is(err, ErrInvalidRange) {
563			t.Fatalf("forged fingerprint err = %v, want ErrInvalidRange", err)
564		}
565		if page != nil {
566			t.Fatalf("forged fingerprint delivered partial page %+v", page)
567		}
568	
569		// A fingerprint that is genuine but belongs to a different position in
570		// the chain is equally invalid for this checkpoint.
571		shifted := first.Checkpoint
572		shifted.EndSeq = 4 // fingerprint still pins seq 8's chain state
573		page, err = s.AuditPage(shifted, first.Next, 1, "", "u1")
574		if !errors.Is(err, ErrInvalidRange) {
575			t.Fatalf("shifted end err = %v, want ErrInvalidRange", err)
576		}
577		if page != nil {
578			t.Fatalf("shifted checkpoint delivered partial page %+v", page)
579		}
580	
581		// The same pinned range presented under another organization's name
582		// cannot page either: the fingerprint binds the organization.
583		foreign := first.Checkpoint
584		foreign.Org = "globex"
585		page, err = s.AuditPage(foreign, first.Next, 1, "", "u1")
586		if !errors.Is(err, ErrInvalidRange) {
587			t.Fatalf("foreign checkpoint err = %v, want ErrInvalidRange", err)
588		}
589		if page != nil {
590			t.Fatalf("foreign checkpoint delivered partial page %+v", page)
591		}
592	
593		// The genuine checkpoint still pages normally after the forgeries.
594		second, err := s.AuditPage(first.Checkpoint, first.Next, 10, "", "u1")
595		if err != nil {
596			t.Fatalf("genuine checkpoint rejected after forgeries: %v", err)
597		}
598		if got := recordSeqs(second.Records); !reflect.DeepEqual(got, []int{4, 8}) {
599			t.Fatalf("genuine continuation seqs = %v, want [4 8]", got)
600		}
601	}
